const RAW="https://raw.githubusercontent.com/grid-kernel/twzrd-live-01q/main/public-machine";
const SPRAT="https://raw.githubusercontent.com/twzrd-sol/sprat-brief/main/sprat.json";
export async function loadBoardJson(){
  const board=await(await fetch(RAW+"/board.json",{cache:"no-store"})).json();
  try{
    const health=await(await fetch("https://intel.twzrd.xyz/health",{headers:{accept:"application/json"},cache:"no-store"})).json();
    const d=health.day0||{};
    const funnel={external_cards:d.free_card_hits_external??0,gate_evals:d.gate_evals??0,gate_blocks:d.gate_blocks??0,paid_external:d.paid_trust_payer_external??0};
    const st=(k,v)=>k==="external_cards"?(v<=0?"empty":v<50?"thin":v<500?"moving":"healthy"):(k==="gate_evals"||k==="gate_blocks")?(v<=0?"empty":v<10?"thin":v<100?"moving":"healthy"):(v<=0?"empty":v<5?"thin":v<50?"moving":"healthy");
    let diagnosis=board.live?.diagnosis||"";
    if(funnel.gate_evals===0&&funnel.external_cards>0) diagnosis="Advisory demand exists without enforcement. Free cards are happening; nobody has installed the buyer gate. Lead with refuse-before-sign.";
    else if(funnel.gate_evals===0&&funnel.external_cards===0) diagnosis="Infra is live; demand is not. Zero external free cards and zero gate_evals.";
    board.live={ok:true,fetched_at:new Date().toISOString(),health:{status:health.status,package_version:health.package_version,network:health.network,mode:health.mode,settle_gate_enforcing:health.settle_gate_enforcing,settle_gate_shadow:health.settle_gate_shadow,service_catalog:health.service_catalog},day0:d,funnel,funnel_status:{external_cards:st("external_cards",funnel.external_cards),gate_evals:st("gate_evals",funnel.gate_evals),gate_blocks:st("gate_blocks",funnel.gate_blocks),paid_external:st("paid_external",funnel.paid_external)},diagnosis};
    board.generated_at=new Date().toISOString();
  }catch(e){board.live={...(board.live||{}),ok:false,error:String(e),fetched_at:new Date().toISOString()};}
  try{
    const sprat=await(await fetch(SPRAT,{cache:"no-store"})).json();
    if(board.cf_strategy){
      board.cf_strategy={...board.cf_strategy,source_schema_version:sprat.schema_version||board.cf_strategy.source_schema_version,thesis:sprat.thesis||board.cf_strategy.thesis,decision:{...board.cf_strategy.decision,summary:sprat.decision_2026_08_11?.summary||board.cf_strategy.decision?.summary,pick:sprat.decision_2026_08_11?.pick||board.cf_strategy.decision?.pick},supply_lanes:sprat.supply_lanes||board.cf_strategy.supply_lanes,posture:sprat.posture||board.cf_strategy.posture,live_source:true,fetched_at:new Date().toISOString()};
    }
  }catch{if(board.cf_strategy){board.cf_strategy.live_source=false;board.cf_strategy.fetched_at=new Date().toISOString();}}
  return board;
}
export function compactCf(cf){if(!cf)return null;return{schema:cf.schema,source_schema_version:cf.source_schema_version,live_source:cf.live_source,pick:cf.decision?.pick,thesis:cf.thesis?.headline,decision_summary:cf.decision?.summary,ship_now:cf.posture?.ship_now,hold:cf.posture?.hold,ready_not_shipped:cf.posture?.ready_not_shipped,guardrail:cf.posture?.guardrail,signals:{A:{id:cf.signals?.A?.id,status:cf.signals?.A?.status},B:{id:cf.signals?.B?.id,status:cf.signals?.B?.status}},not_this_board:cf.not_this_board};}
export async function loadRaw(n){const r=await fetch(RAW+"/"+n,{cache:"no-store"});if(!r.ok)throw new Error(n+" "+r.status);return r.text();}

import {cors,originFromReq} from "../lib/http.mjs";
import {loadBoardJson} from "../lib/load.mjs";
export default async function handler(req,res){cors(res);if(req.method==="OPTIONS")return res.status(204).end();try{const board=await loadBoardJson();const o=originFromReq(req);board.product={...board.product,human_ui:o+"/",machine_start:o+"/llms.txt"};board.endpoints={...(board.endpoints||{}),human_ui:o+"/",llms_txt:o+"/llms.txt",board_json:o+"/api/board",status_json:o+"/api/board/status",moves_json:o+"/api/board/moves",openapi:o+"/api/openapi.json",intel_health_proxy:o+"/api/intel-health"};res.setHeader("content-type","application/json; charset=utf-8");res.status(200).send(JSON.stringify(board,null,2));}catch(e){res.status(500).json({error:String(e)});}}

import {cors,originFromReq} from "../lib/http.mjs";
import {loadBoardJson,compactCf} from "../lib/load.mjs";
export default async function handler(req,res){cors(res);if(req.method==="OPTIONS")return res.status(204).end();try{const board=await loadBoardJson();const o=originFromReq(req);res.setHeader("content-type","application/json; charset=utf-8");res.status(200).send(JSON.stringify({schema:"twzrd.live_board_status/v1",id:board.id,version:board.version,generated_at:board.generated_at,north_star:board.north_star,live:board.live,cf_strategy:compactCf(board.cf_strategy),next_actions:(board.next_actions||[]).map(m=>({id:m.id,title:m.title,impact:m.impact,horizon:m.horizon,phase:m.phase,metric:m.metric})),dogfood:board.dogfood,endpoints:{...(board.endpoints||{}),human_ui:o+"/",llms_txt:o+"/llms.txt",board_json:o+"/api/board"}},null,2));}catch(e){res.status(500).json({error:String(e)});}}

import {cors} from "../lib/http.mjs";
import {loadBoardJson} from "../lib/load.mjs";
export default async function handler(req,res){cors(res);if(req.method==="OPTIONS")return res.status(204).end();try{const board=await loadBoardJson();res.setHeader("content-type","application/json; charset=utf-8");res.status(200).send(JSON.stringify({schema:"twzrd.live_board_moves/v1",id:board.id,version:board.version,generated_at:board.generated_at,count:(board.moves||[]).length,phases:board.phases,moves:board.moves},null,2));}catch(e){res.status(500).json({error:String(e)});}}

import {cors,originFromReq} from "../lib/http.mjs";
import {loadRaw,loadBoardJson} from "../lib/load.mjs";
export default async function handler(req,res){cors(res);if(req.method==="OPTIONS")return res.status(204).end();try{let text=await loadRaw("llms.txt");const board=await loadBoardJson();text=text.replace(/^generated_at:.*$/m,"generated_at: "+board.generated_at);const o=originFromReq(req);if(!text.includes(o))text+=`

## This host

- ${o}/llms.txt
- ${o}/api/board
`;res.setHeader("content-type","text/markdown; charset=utf-8");res.status(200).send(text);}catch(e){res.status(500).send(String(e));}}
